CREATE TYPE "public"."sv_capture_task_status" AS ENUM ('PENDING_CAPTURE', 'AWAITING_MANUAL_CAPTURE', 'SUBMITTED_FOR_REVIEW', 'ACCEPTED', 'REJECTED', 'NEEDS_CORRECTION', 'INSUFFICIENT_EVIDENCE', 'SURFACE_UNAVAILABLE');
CREATE TYPE "public"."sv_ordering_state" AS ENUM ('EXPLICIT_ORDER', 'UNORDERED', 'UNKNOWN');
CREATE TYPE "public"."sv_mention_role" AS ENUM ('TARGET', 'PARENT', 'CHILD', 'COMPETITOR', 'OTHER');
CREATE TYPE "public"."sv_match_status" AS ENUM ('EXACT_ALIAS', 'REVIEWED_MATCH', 'UNRESOLVED');
CREATE TABLE "sv_pilot_cycles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "project_id" uuid NOT NULL REFERENCES "sv_projects"("id"), "lock_id" uuid NOT NULL REFERENCES "sv_configuration_locks"("id"), "status" text DEFAULT 'CREATED' NOT NULL, "expected_observations" integer NOT NULL, "created_observations" integer DEFAULT 0 NOT NULL, "capture_protocol_version" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_capture_tasks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "pilot_cycle_id" uuid NOT NULL REFERENCES "sv_pilot_cycles"("id"), "scenario_id" uuid NOT NULL REFERENCES "sv_scenarios"("id"), "context_hash" text NOT NULL, "context_snapshot" jsonb NOT NULL, "repeat_index" integer NOT NULL, "query_text_snapshot" text NOT NULL, "target_entity_ids_snapshot" jsonb DEFAULT '[]' NOT NULL, "status" "sv_capture_task_status" DEFAULT 'PENDING_CAPTURE' NOT NULL, "idempotency_key" text, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_local_observations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "capture_task_id" uuid NOT NULL REFERENCES "sv_capture_tasks"("id"), "captured_by" text NOT NULL, "captured_at" timestamptz NOT NULL, "submitted_at" timestamptz DEFAULT now() NOT NULL, "reviewed_by" text, "reviewed_at" timestamptz, "review_status" text DEFAULT 'SUBMITTED_FOR_REVIEW' NOT NULL, "validity" text, "invalid_reason" text, "ordering_state" "sv_ordering_state" DEFAULT 'UNKNOWN' NOT NULL, "transcript" text NOT NULL, "query_text" text NOT NULL, "content_sha256" text NOT NULL, "version" integer DEFAULT 1 NOT NULL, "supersedes_observation_id" uuid REFERENCES "sv_local_observations"("id"), "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_observation_mentions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "observation_id" uuid NOT NULL REFERENCES "sv_local_observations"("id"), "raw_mention_text" text NOT NULL, "matched_entity_id" uuid REFERENCES "sv_entities"("id"), "mention_role" "sv_mention_role" NOT NULL, "match_status" "sv_match_status" NOT NULL, "match_confidence" numeric(5,4), "explicit_position" integer, "ordering_basis" text, "factual_error" boolean DEFAULT false NOT NULL, "evidence_locator" text);
CREATE TABLE "sv_observation_evidence_assets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "observation_id" uuid NOT NULL REFERENCES "sv_local_observations"("id"), "asset_type" text NOT NULL, "mime_type" text NOT NULL, "size_bytes" integer NOT NULL, "sha256" text NOT NULL, "sequence_index" integer NOT NULL, "private_object_reference" text NOT NULL, "uploaded_by" text NOT NULL, "captured_at" timestamptz NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_audit_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "actor_id" text NOT NULL, "event" text NOT NULL, "subject_kind" text NOT NULL, "subject_id" text NOT NULL, "details" jsonb DEFAULT '{}' NOT NULL, "at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "sv_pilot_cycles_org_idx" ON "sv_pilot_cycles" ("organization_id"); CREATE INDEX "sv_pilot_cycles_project_idx" ON "sv_pilot_cycles" ("project_id");
CREATE UNIQUE INDEX "sv_capture_tasks_matrix_unique" ON "sv_capture_tasks" ("pilot_cycle_id", "scenario_id", "context_hash", "repeat_index"); CREATE UNIQUE INDEX "sv_capture_tasks_org_idempotency_unique" ON "sv_capture_tasks" ("organization_id", "idempotency_key"); CREATE INDEX "sv_capture_tasks_org_idx" ON "sv_capture_tasks" ("organization_id");
CREATE UNIQUE INDEX "sv_local_observations_task_unique" ON "sv_local_observations" ("capture_task_id"); CREATE INDEX "sv_local_observations_org_idx" ON "sv_local_observations" ("organization_id");
CREATE INDEX "sv_observation_mentions_observation_idx" ON "sv_observation_mentions" ("observation_id"); CREATE INDEX "sv_observation_mentions_org_idx" ON "sv_observation_mentions" ("organization_id");
CREATE INDEX "sv_observation_evidence_assets_observation_idx" ON "sv_observation_evidence_assets" ("observation_id"); CREATE INDEX "sv_observation_evidence_assets_org_idx" ON "sv_observation_evidence_assets" ("organization_id");
CREATE INDEX "sv_audit_events_org_at_idx" ON "sv_audit_events" ("organization_id", "at");
ALTER TABLE "sv_pilot_cycles" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_capture_tasks" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_local_observations" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_observation_mentions" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_observation_evidence_assets" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_audit_events" ENABLE ROW LEVEL SECURITY;
